# Inserite in extra.py: GRAFICI[lezione] = (titolo della slide dopo cui inserire, slide)
from h import *

def V(titolo, img, voce, didascalia):
    # la fonte è già scritta sotto il grafico: non viene letta dalla voce
    return G(titolo, img, [voce])

